# Generated by build.py from recipe.yml for recipe http-rotate-a-fixed-bearer-token. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p site
printf '%s\n' 'hello from surl' > site/hello.txt
printf '%s\n' 'control-token-0123456789abcdefghij' > token.txt
printf '%s' '{"user":"","password":"token-one"}' > bearer.json
printf '%s' '{"password":"token-two"}' > rotate.json
openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"
surl -v --log-file surl.log --directory site --cert server.pem --key server.key --control http://127.0.0.1:8081 --control-token-file token.txt https://127.0.0.1:8080/ &
sleep 1
curl -s -o /dev/null -w "%{scheme} %{response_code}\n" --json @bearer.json -H "Authorization: Bearer control-token-0123456789abcdefghij" http://127.0.0.1:8081/v1/accounts --next -s -o /dev/null -w "%{scheme} %{response_code}\n" --cacert server.pem https://127.0.0.1:8080/hello.txt --next -s -o /dev/null -w "%{scheme} %{response_code}\n" --cacert server.pem --oauth2-bearer token-one https://127.0.0.1:8080/hello.txt
kill $(jobs -p)
